def tree_diameter(level_order):
    if not level_order or level_order[0] is None:
        return 0
    n = len(level_order)
    left = [None] * n
    right = [None] * n
    child = 1
    for i in range(n):
        if level_order[i] is None:
            continue
        if child < n:
            if level_order[child] is not None:
                left[i] = child
            child += 1
        if child < n:
            if level_order[child] is not None:
                right[i] = child
            child += 1
    best = 0

    def height(i):
        nonlocal best
        if i is None:
            return 0
        lh = height(left[i])
        rh = height(right[i])
        best = max(best, lh + rh)
        return 1 + max(lh, rh)

    height(0)
    return best
